python -c "
import numpy as np
L=open('init.xyz').read().split('\n')[2:95]
S=[l.split()[0] for l in L]; X=np.array([[float(x) for x in l.split()[1:]] for l in L])
D=np.linalg.norm(X[:,None]-X[None],axis=2); np.fill_diagonal(D,9)
idx=np.argwhere(D<1.0)
print(len(idx)//2,'contacts <1.0 A'); 
for i,j in idx:
    if i<j: print(S[i],i,S[j],j,round(D[i,j],2))
"
